CREATE DATABASE IF NOT EXISTS qlkho_domdom CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE qlkho_domdom;
CREATE TABLE IF NOT EXISTS vai_tro(MaVaiTro VARCHAR(20) PRIMARY KEY,TenVaiTro VARCHAR(100) NOT NULL UNIQUE,MoTa VARCHAR(300),TrangThai ENUM('ACTIVE','LOCKED') NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS quyen(MaQuyen VARCHAR(30) PRIMARY KEY,TenQuyen VARCHAR(100) NOT NULL UNIQUE,MoTa VARCHAR(300));
CREATE TABLE IF NOT EXISTS vai_tro_quyen(MaVaiTro VARCHAR(20),MaQuyen VARCHAR(30),PRIMARY KEY(MaVaiTro,MaQuyen),FOREIGN KEY(MaVaiTro) REFERENCES vai_tro(MaVaiTro),FOREIGN KEY(MaQuyen) REFERENCES quyen(MaQuyen));
CREATE TABLE IF NOT EXISTS tai_khoan(MaTaiKhoan VARCHAR(20) PRIMARY KEY,TenDangNhap VARCHAR(50) NOT NULL UNIQUE,MatKhauHash VARCHAR(255) NOT NULL,HoTen VARCHAR(120) NOT NULL,Email VARCHAR(150),SoDienThoai VARCHAR(30),MaVaiTro VARCHAR(20) NOT NULL,TrangThai ENUM('ACTIVE','LOCKED') NOT NULL DEFAULT 'ACTIVE',NgayTao DATETIME DEFAULT CURRENT_TIMESTAMP,LanDangNhapCuoi DATETIME NULL,FOREIGN KEY(MaVaiTro) REFERENCES vai_tro(MaVaiTro));
CREATE TABLE IF NOT EXISTS phieu_hang_loi(MaPhieu VARCHAR(24) PRIMARY KEY,NgayLap DATE NOT NULL,LoaiHang ENUM('NGUYEN_LIEU','THANH_PHAM') NOT NULL,MaHang VARCHAR(30) NOT NULL,TenHang VARCHAR(150) NOT NULL,SoLuong DECIMAL(12,2) NOT NULL,DonViTinh VARCHAR(30) NOT NULL,LyDo VARCHAR(250) NOT NULL,HuongXuLy ENUM('TIEU_HUY','TRA_NCC','TAI_CHE') NOT NULL,NhaCungCap VARCHAR(150),TrangThai ENUM('CHO_DUYET','DANG_XU_LY','DA_XU_LY','TU_CHOI') NOT NULL DEFAULT 'CHO_DUYET',GhiChu TEXT,HinhAnh VARCHAR(255),MaNguoiLap VARCHAR(20) NOT NULL,NgayTao DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(MaNguoiLap) REFERENCES tai_khoan(MaTaiKhoan));
CREATE TABLE IF NOT EXISTS lich_su_thao_tac(MaLichSu BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,MaTaiKhoan VARCHAR(20),ThoiGian DATETIME DEFAULT CURRENT_TIMESTAMP,HanhDong VARCHAR(100) NOT NULL,DoiTuong VARCHAR(100),MaDoiTuong VARCHAR(30),NoiDung TEXT,FOREIGN KEY(MaTaiKhoan) REFERENCES tai_khoan(MaTaiKhoan) ON DELETE SET NULL);
